INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann Überlappung durch falsche Subnetzplanung entstehen?', 2, '[{"text": "Ja", "correct": true, "because": "Bereiche dürfen sich nicht überschneiden"}, {"text": "Nein", "correct": false, "because": "Planungsfehler möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme verhindert Überlappung bei 192.168.1.0/24 mit /26?', 3, '[{"text": "Korrekte Inkrementierung", "correct": true, "because": "64er-Schritte vermeiden Überschneidung"}, {"text": "Zufällige Zuweisung", "correct": false, "because": "Erhöht Risiko"}, {"text": "Kleinere Maske", "correct": false, "because": "Ändert Bereiche nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Überlappung führt zu IP-Konflikten. b) Adressverlust ist unvermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Adressverlust minimierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Fehlervermeidung?', 4, '[{"text": "Inkrement", "correct": false, "because": "Bestimmt Bereiche"}, {"text": "Hostanzahl", "correct": false, "because": "Beeinflusst Verlust"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Überlappung bei 192.168.1.0/26 und 192.168.1.64/27 möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "64-127 vs. 64-95 überschneidet"}, {"text": "Nein", "correct": false, "because": "Bereiche kollidieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler entsteht, wenn ich 10.0.0.0/24 doppelt mit /25 und /26 teile?', 3, '[{"text": "Überlappung", "correct": true, "because": "Bereiche nicht eindeutig"}, {"text": "Adressverlust", "correct": false, "because": "Primär Überlappung"}, {"text": "Keine Fehler", "correct": false, "because": "Kollision unvermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen vermeiden Fehler?', 5, '[{"text": "Eindeutige Bereiche", "correct": true, "because": "Verhindert Überlappung"}, {"text": "Passende Masken", "correct": true, "because": "Minimiert Verlust"}, {"text": "Zufällige Zuweisung", "correct": false, "because": "Erhöht Risiko"}, {"text": "Protokollwechsel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Überlappung ist bei /24 mit /25 möglich. b) Adressverlust betrifft nur kleine Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) betrifft alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Fehlervermeidung?', 4, '[{"text": "Bereichsplanung", "correct": false, "because": "Verhindert Überlappung"}, {"text": "Hostbedarf", "correct": false, "because": "Minimiert Verlust"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verursacht /26 auf 192.168.1.0/25 Adressverlust?', 2, '[{"text": "Ja", "correct": true, "because": "Nur 2 von 4 Subnetzen nutzbar"}, {"text": "Nein", "correct": false, "because": "Teilbereich ungenutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich überlappt bei 192.168.1.0/26 mit 192.168.1.32/27?', 4, '[{"text": "192.168.1.32-192.168.1.63", "correct": true, "because": "32-63 kollidiert"}, {"text": "192.168.1.0-192.168.1.31", "correct": false, "because": "Keine Überschneidung"}, {"text": "192.168.1.64-192.168.1.95", "correct": false, "because": "Anderes Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Adressverlust nur bei /30 auftritt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann bei jeder Maske passieren"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Fehlervermeidung?', 3, '[{"text": "Korrekte Bereiche", "correct": true, "because": "Verhindert Überlappung"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Falsches Inkrement verursacht Überlappung. b) Adressverlust ist immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft unvermeidbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler vermeide ich bei 10.0.0.0/24?', 5, '[{"text": "Überlappung durch /25", "correct": true, "because": "128er-Schritte klar trennen"}, {"text": "Adressverlust durch /30", "correct": true, "because": "Nur 2 Hosts nutzbar"}, {"text": "Überlappung durch /32", "correct": false, "because": "Einzeladresse"}, {"text": "Verlust durch /16", "correct": false, "because": "Größerer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Fehlervermeidung unwichtig?', 3, '[{"text": "Inkrement", "correct": false, "because": "Bestimmt Bereiche"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Grenzen"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verursacht /27 auf 192.168.1.0/26 Überlappung?', 3, '[{"text": "Ja", "correct": true, "because": "32er-Schritte in 64er-Bereich"}, {"text": "Nein", "correct": false, "because": "Kollision unvermeidbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /28 auf 172.16.0.0/24 Adressverlust hat?', 2, '[{"text": "Ja", "correct": true, "because": "16er-Schritte nutzen nicht alles"}, {"text": "Nein", "correct": false, "because": "Teilbereich ungenutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske vermeidet Überlappung bei 192.168.1.0/25 und 192.168.1.128/26?', 4, '[{"text": "/26", "correct": true, "because": "64er-Schritte trennen klar"}, {"text": "/24", "correct": false, "because": "Zu groß"}, {"text": "/27", "correct": false, "because": "32er-Schritte überlappen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Ansatz minimiert Adressverlust bei 10.0.0.0/24?', 3, '[{"text": "/25", "correct": true, "because": "128 Hosts effizient"}, {"text": "/30", "correct": false, "because": "Hoher Verlust"}, {"text": "/16", "correct": false, "because": "Zu groß"}]');
